func qaConfigFields() []string {
	return []string{
		"qa.model", "qa.variant", "qa.changed_paths", "qa.primary_shards",
		"qa.boundary_shards", "qa.follow_up_shards", "qa.total_shards",
		"qa.pending_entries", "qa.changed_paths_per_shard",
