func TestHealthValidAndInvalidWorkspace(t *testing.T) {
	restore := stubRuntimeHealth(t, []healthCheck{{Name: "runtime.runtime_available", Status: "ok", Message: "fake runtime ready"}}, nil)
	defer restore()
	dir := initializedWorkspace(t)
	stdout, stderr, status := runForTest([]string{"--workspace", dir, "health"})
	if status != ExitOK {
		t.Fatalf("status = %d, stderr = %q", status, stderr)
	}
	assertContains(t, stdout, "workspace.discovery: ok")
	assertContains(t, stdout, "runtime.runtime_available: ok - fake runtime ready")

	if err := os.Remove(filepath.Join(dir, "ultraplan.yml")); err != nil {
		t.Fatal(err)
	}
	stdout, stderr, status = runForTest([]string{"--workspace", dir, "health", "--json"})
	if status != ExitWorkspace {
		t.Fatalf("status = %d, want %d, stdout = %q stderr = %q", status, ExitWorkspace, stdout, stderr)
	}
	assertContains(t, stdout, `"status": "fail"`)
	assertContains(t, stderr, "missing ultraplan.yml")
}

func TestHealthEnvironmentSummaryCountsAllKnownOverrides(t *testing.T) {
	restore := stubRuntimeHealth(t, []healthCheck{{Name: "runtime.runtime_available", Status: "ok"}}, nil)
	defer restore()
	dir := initializedWorkspace(t)
	stdout, stderr, status := runForTestWithEnv([]string{"--workspace", dir, "health"}, map[string]string{
		"ULTRAPLAN_WORKSPACE":            dir,
		"ULTRAPLAN_RUNTIME_DEFAULT":      "opencode",
		"ULTRAPLAN_MODEL_DEFAULT":        "provider/default",
		"ULTRAPLAN_MODEL_PRIMARY":        "provider/primary",
		"ULTRAPLAN_MODEL_BACKUP":         "provider/backup",
		"ULTRAPLAN_DEFAULT_VARIANT":      "high",
		"ULTRAPLAN_DEFAULT_PARALLEL":     "4",
		"ULTRAPLAN_DEFAULT_TIMEOUT":      "45m",
		"ULTRAPLAN_DEFAULT_RETRIES":      "2",
		"ULTRAPLAN_LOG_FORMAT":           "json",
		"ULTRAPLAN_LOG_LEVEL":            "debug",
		"ULTRAPLAN_AGENTWRAP_EXECUTABLE": "opencode",
		"ULTRAPLAN_UNKNOWN_NOT_COUNTED":  "ignored",
	})
	if status != ExitOK {
		t.Fatalf("status = %d, stderr = %q", status, stderr)
	}
	assertContains(t, stdout, "environment.overrides: ok - 12 ULTRAPLAN_ override(s) present")
}

func TestHealthRuntimeFailureUsesRuntimeExit(t *testing.T) {
	restore := stubRuntimeHealth(t, []healthCheck{{Name: "runtime.runtime_available", Status: "fail", Message: "missing executable"}}, errors.New("missing executable"))
	defer restore()
	dir := initializedWorkspace(t)

	stdout, stderr, status := runForTest([]string{"--workspace", dir, "health", "--json"})
	if status != ExitRuntime {
		t.Fatalf("status = %d, want %d, stdout = %q stderr = %q", status, ExitRuntime, stdout, stderr)
	}
	assertContains(t, stdout, `"status": "fail"`)
	assertContains(t, stdout, `"name": "runtime.runtime_available"`)
	assertContains(t, stderr, "runtime.health")
}

func TestHealthJSONEnvelopeAndRedaction(t *testing.T) {
	restore := stubRuntimeHealth(t, []healthCheck{{ID: "runtime.runtime_available", Name: "runtime.runtime_available", Status: "fail", Message: "Bearer sk-test-secret"}}, errors.New("Bearer sk-test-secret"))
	defer restore()
	dir := initializedWorkspace(t)

	stdout, _, status := runForTest([]string{"--workspace", dir, "health", "--json"})
	if status != ExitRuntime {
		t.Fatalf("status = %d stdout = %q", status, stdout)
	}
	var payload struct {
		SchemaVersion int    `json:"schema_version"`
		Command       string `json:"command"`
		Status        string `json:"status"`
		Result        struct {
			SchemaVersion int           `json:"schema_version"`
			Checks        []healthCheck `json:"checks"`
		} `json:"result"`
	}
	if err := json.Unmarshal([]byte(stdout), &payload); err != nil {
		t.Fatalf("invalid json: %v\n%s", err, stdout)
	}
	if payload.SchemaVersion != 1 || payload.Command != "health" || payload.Status != "fail" || payload.Result.SchemaVersion != 1 {
		t.Fatalf("unexpected payload: %+v", payload)
	}
	assertContains(t, stdout, `"id": "runtime.runtime_available"`)
	assertNotContains(t, stdout, "sk-test-secret")
	assertNotContains(t, stdout, "\x1b[")
}

func stubRuntimeHealth(t *testing.T, checks []healthCheck, err error) func() {
	t.Helper()
	orig := runtimeHealthChecks
	runtimeHealthChecks = func(context.Context, string, config.Config) ([]healthCheck, error) {
		return checks, err
	}
	return func() { runtimeHealthChecks = orig }
}

package config

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

func TestLoadPrecedenceAndValidation(t *testing.T) {
	root := t.TempDir()
	if err := os.WriteFile(filepath.Join(root, "ultraplan.yml"), []byte(`version: 1
runtime:
  default: opencode
models:
  default: workspace/default
  primary: workspace/primary
  backup: workspace/backup
execution:
  default_variant: medium
  default_parallel: 2
  default_timeout: 10m
  default_retries: 1
logging:
  format: text
  level: info
agentwrap:
  executable: opencode
  required_health:
    - runtime_available
planning:
  requirements_model: openai/gpt-5.5
  requirements_variant: high
  code_context_model: workspace/context
  code_context_variant: high
  sprint_index_model: openai/gpt-5.5
  sprint_index_variant: high
`), 0o644); err != nil {
		t.Fatal(err)
	}
	logFormat := "json"
	effective, err := Load(LoadOptions{
		WorkspaceRoot: root,
		Env: func(key string) string {
			if key == "ULTRAPLAN_MODEL_PRIMARY" {
				return "env/primary"
			}
			if key == "ULTRAPLAN_CODE_CONTEXT_MODEL" {
				return "env/context"
			}
			return ""
		},
		CLI: CLIOverrides{LogFormat: &logFormat},
	})
	if err != nil {
		t.Fatal(err)
	}
	if effective.Config.Models.Default != "workspace/default" {
		t.Fatalf("workspace value not loaded: %+v", effective.Config.Models)
	}
	if effective.Config.Models.Primary != "env/primary" {
		t.Fatalf("env did not win: %+v", effective.Config.Models)
	}
	if effective.Config.Logging.Format != "json" {
		t.Fatalf("cli did not win: %+v", effective.Config.Logging)
	}
	if effective.Config.Planning.RequirementsModel != "openai/gpt-5.5" || effective.Config.Planning.RequirementsVariant != "high" {
		t.Fatalf("requirements planning config not loaded: %+v", effective.Config.Planning)
	}
	if effective.Config.Planning.SprintIndexModel != "openai/gpt-5.5" || effective.Config.Planning.SprintIndexVariant != "high" {
		t.Fatalf("planning config not loaded: %+v", effective.Config.Planning)
	}
	if effective.Config.Planning.CodeContextModel != "env/context" || effective.Config.Planning.CodeContextVariant != "high" || effective.Sources["planning.code_context_model"] != "env" || effective.Sources["planning.code_context_variant"] != "workspace" {
		t.Fatalf("code-context planning config/source not resolved: config=%+v sources=%+v", effective.Config.Planning, effective.Sources)
	}
}

func TestRedactSensitiveValues(t *testing.T) {
	e := Effective{Config: Defaults()}
	e.Config.Models.Default = "secret/model-token"
	e.Config.Agentwrap.Env = []string{"OPENAI_API_KEY=secret"}
	e.Config.Planning.CodeContextModel = "secret/context-token"
	redacted := Redact(e)
	if redacted.Models.Default != "[REDACTED]" {
		t.Fatalf("secret was not redacted: %q", redacted.Models.Default)
	}
	if redacted.Agentwrap.Env[0] != "[REDACTED]" {
		t.Fatalf("env secret was not redacted: %q", redacted.Agentwrap.Env[0])
	}
	if redacted.Planning.CodeContextModel != "[REDACTED]" {
		t.Fatalf("code-context model was not redacted: %q", redacted.Planning.CodeContextModel)
	}
	if redacted.Git != e.Config.Git {
		t.Fatalf("git config missing from redacted projection: got %+v want %+v", redacted.Git, e.Config.Git)
	}
	if got := RedactValue("lock.command", "ultraplan study demo run-loop --api-key=secret-value"); got != "[REDACTED]" {
		t.Fatalf("dash-form api key was not redacted: %q", got)
	}
}

func TestLoadAgentwrapListThenScalarFields(t *testing.T) {
	root := t.TempDir()
	if err := os.WriteFile(filepath.Join(root, "ultraplan.yml"), []byte(`version: 1
agentwrap:
  executable: opencode
  required_health:
    - runtime_available
    - structured_output
    - workdir
  sandbox: workspace_write
  permission_mode: restricted
  permission_default: allow
`), 0o644); err != nil {
		t.Fatal(err)
	}
	effective, err := Load(LoadOptions{WorkspaceRoot: root})
	if err != nil {
		t.Fatal(err)
	}
	if got := effective.Config.Agentwrap.RequiredHealth; len(got) != 3 || got[0] != "runtime_available" || got[2] != "workdir" {
		t.Fatalf("RequiredHealth = %+v", got)
	}
	if effective.Config.Agentwrap.Sandbox != "workspace_write" {
		t.Fatalf("Sandbox = %q", effective.Config.Agentwrap.Sandbox)
	}
	if effective.Config.Agentwrap.PermissionMode != "restricted" {
		t.Fatalf("PermissionMode = %q", effective.Config.Agentwrap.PermissionMode)
	}
	if effective.Config.Agentwrap.PermissionDefault != "allow" {
		t.Fatalf("PermissionDefault = %q", effective.Config.Agentwrap.PermissionDefault)
	}
}

func TestValidateRejectsBadConfig(t *testing.T) {
	c := Defaults()
	c.Execution.DefaultTimeout = "nope"
	if err := Validate(c); err == nil {
		t.Fatal("expected validation error")
